import falcon
from falcon import testing

def test_bug():
    req = testing.create_req(query_string='foo=bar&foo=baz')
    try:
        req.get_param('foo', require_single=True)
    except falcon.HTTPInvalidParam:
        return
    except falcon.HTTPBadRequest:
        return
    raise AssertionError("Expected an exception when multiple values are present and require_single=True is specified")

import falcon
from io import BytesIO

def test_bug():
    env = {'REQUEST_METHOD': 'GET', 'QUERY_STRING': 'foo=bar&foo=baz', 'PATH_INFO': '/', 'wsgi.errors': BytesIO(), 'wsgi.input': BytesIO()}
    req = falcon.Request(env)
    try:
        req.get_param('foo', require_single=True)
    except TypeError:
        raise
    except Exception:
        pass
    else:
        raise AssertionError('Expected an exception for multiple values when require_single=True')
